"""Embers generated by the burning vegetation cells around each building (non-burnable-building runs).
Usage: python ember_generation_near_buildings.py RUN_DIR [RUN_DIR ...]   (e.g. ember_count/nobldg/spot2 ...)

ELMFIRE writes no per-cell generation output for the Eulerian model, so generation is computed from the
PER-MW rule (elmfire_spotting.f90, EMBER_TO_EMIT_PER_CELL): rate = FLIN * dx * EMBER_GR_PER_MW_VEGE / 1000
embers/s, emitted for TAU_EMBERGEN = 10 s after the cell's time of arrival (CALC_SPOTTING_DURATION):
    generated = FLIN * 30 * 33.3 / 1000 * 10  ~= 10 * FLIN   (FLIN in kW/m)
This is the intended amount. The model only emits over the part of the 10 s window that overlaps its time steps
(elmfire_level_set.f90 ~1271), so the realised total is lower (embers landed / intended = 0.26-0.53 in the
runs checked). The flin output is surface + canopy intensity; generation uses surface only.

Per building (vulnerability/features.csv point, its 30 m cell), per run: vegetation cells (fuel >= 100) in the
8 neighbours (ring 1, ~30-40 m) and in the 24 cells of rings 1-2 (~60 m): number burned, embers generated (sum),
largest FLIN. Writes <common parent>/ember_generation_near_buildings.csv and prints a summary by label.
"""
import sys, os, glob
import numpy as np
import pandas as pd
from osgeo import gdal
gdal.UseExceptions()
DX, GR_VEGE, TAU = 30.0, 33.3, 10.0

runs = [r.rstrip('/') for r in sys.argv[1:]]
out_dir = runs[0] if len(runs) == 1 else os.path.commonpath(runs)
seeds = [s for r in runs for s in sorted(glob.glob(r + '/seed_*/outputs'))]
L = gdal.Open(runs[0] + '/inputs/landscape.tif'); fm = L.GetRasterBand(4).ReadAsArray(); gt = L.GetGeoTransform()
veg = fm >= 100

f = pd.read_csv(os.path.join(os.path.dirname(__file__), '..', 'vulnerability', 'features.csv'))
col = ((f.x - gt[0]) / gt[1]).astype(int).values; row = ((f.y - gt[3]) / gt[5]).astype(int).values
ring1 = [(dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx]
ring12 = [(dy, dx) for dy in range(-2, 3) for dx in range(-2, 3) if dy or dx]
R1 = [(row + dy, col + dx) for dy, dx in ring1]; R12 = [(row + dy, col + dx) for dy, dx in ring12]
f['n_veg_ring1'] = sum(veg[r, c] for r, c in R1); f['n_veg_ring12'] = sum(veg[r, c] for r, c in R12)

G1, G12, F1, B1 = [], [], [], []
for s in seeds:
    fl = gdal.Open(glob.glob(s + '/flin_*.tif')[0]).ReadAsArray().astype(float)
    toa = gdal.Open(glob.glob(s + '/time_of_arrival_*.tif')[0]).ReadAsArray()
    bv = veg & (toa > 0)
    flin = np.where(bv, np.clip(fl, 0, None), 0.0)
    gen = flin * DX * GR_VEGE / 1000.0 * TAU
    G1.append(sum(gen[r, c] for r, c in R1)); G12.append(sum(gen[r, c] for r, c in R12))
    F1.append(np.max([flin[r, c] for r, c in R1], 0)); B1.append(sum(bv[r, c] for r, c in R1))
G1, G12, F1, B1 = map(np.array, (G1, G12, F1, B1))            # runs x buildings
reached = B1 > 0
f['n_runs'] = len(seeds)
f['p_veg_nb_burned'] = reached.mean(0)                        # share of runs with a burning vegetation neighbour
f['gen_ring1_mean'] = G1.mean(0)                              # embers generated by ring-1 vegetation, mean over all runs
f['gen_ring1_when_burned'] = np.where(reached.any(0), G1.sum(0) / np.maximum(reached.sum(0), 1), 0)
f['gen_ring12_mean'] = G12.mean(0)
f['flin_max_ring1_when_burned'] = np.where(reached.any(0), (F1 * reached).sum(0) / np.maximum(reached.sum(0), 1), 0)
cols = ['id', 'x', 'y', 'y_A', 'n_veg_ring1', 'n_veg_ring12', 'n_runs', 'p_veg_nb_burned', 'gen_ring1_mean',
        'gen_ring1_when_burned', 'gen_ring12_mean', 'flin_max_ring1_when_burned']
f[cols].round(3).to_csv(out_dir + '/ember_generation_near_buildings.csv', index=False)

print(f'{", ".join(os.path.basename(r) for r in runs)}: {len(seeds)} runs')
for name, sel in [('destroyed (y_A=1)', f.y_A == 1), ('not destroyed (y_A=0)', f.y_A == 0)]:
    g = f[sel]; w = g[g.p_veg_nb_burned > 0]
    print(f'  {name:22s} n={len(g):4d}  no vegetation neighbour {(g.n_veg_ring1 == 0).mean():4.0%}  '
          f'veg neighbour burned in >=1 run {(g.p_veg_nb_burned > 0).mean():4.0%}  P(veg nb burned) {g.p_veg_nb_burned.mean():.2f}  '
          f'| ring-1 embers generated, when burned: median {w.gen_ring1_when_burned.median():.3g}, p90 {w.gen_ring1_when_burned.quantile(.9):.3g}  '
          f'| max neighbour FLIN median {w.flin_max_ring1_when_burned.median():.3g} kW/m')
